import {CREW,activeCrew,stats} from './world.js';
const escape=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const SKINS=['#bd9270','#af7f60','#ddae8c','#9a6a50','#b88668','#ba9984','#805b47','#c89475','#a77558'];
export function crewSprite(c,small=false){
 const i=Math.max(0,CREW.findIndex(v=>v.id===c.id)),hair=['#625447','#4c3d31','#b8aaa0','#5b342f','#a58a67','#252f46','#272b28','#897155','#292d39'][i];
 return `<svg class="pixel-person ${small?'small':''}" viewBox="0 0 36 48" aria-hidden="true" shape-rendering="crispEdges"><path fill="#050c1370" d="M5 44h26v4H5z"/><path fill="${c.color}" d="M7 26h22v17H7zM3 29h4v11H3zm26 0h4v11h-4z"/><path fill="#263340" d="M9 40h8v7H9zm11 0h8v7h-8z"/><path fill="${SKINS[i]}" d="M11 10h15v15H11zm4 14h8v5h-8zM3 38h4v5H3zm26 0h4v5h-4z"/><path fill="${hair}" d="M9 7h19v8H9zm0 7h4v6H9zm17 0h3v5h-3z"/><path fill="#2b3039" d="M14 17h2v2h-2zm8 0h2v2h-2z"/><path fill="#84584b" d="M17 22h5v1h-5z"/><path fill="#ead7ae" d="M12 29h3v9h-3z"/><path fill="#32434a" d="M20 31h6v4h-6z"/></svg>`;
}
export function messIllustration(s){
 const people=activeCrew(s).map(id=>CREW.find(c=>c.id===id)),spots=[[30,51],[65,50],[20,67],[76,67],[42,76],[58,76]],mugs=[275,370,475,565].map((x,i)=>`<rect x="${x}" y="${288+i%2*26}" width="15" height="17" fill="#c9b99a"/><rect x="${x+15}" y="${291+i%2*26}" width="6" height="9" fill="none" stroke="#c9b99a" stroke-width="3"/>`).join('');
 return `<div class="mess-scene" role="img" aria-label="Illustrated common room aboard ${escape(s.shipName)} with ${people.length} working crew"><svg viewBox="0 0 900 470" shape-rendering="crispEdges" aria-hidden="true"><defs><linearGradient id="mess-window" x2="0" y2="1"><stop stop-color="#22364a"/><stop offset="1" stop-color="#10172b"/></linearGradient><linearGradient id="mess-wall" x2="0" y2="1"><stop stop-color="#344447"/><stop offset="1" stop-color="#273035"/></linearGradient></defs><path fill="#17232c" d="M0 0h900v470H0z"/><path fill="url(#mess-wall)" d="M30 32h840v267H30z"/><path fill="#3a4140" d="M30 299h840l30 171H0z"/><path fill="#121e28" d="M55 57h790v140H55z"/><path fill="url(#mess-window)" d="M66 68h768v117H66z"/><circle cx="690" cy="145" r="72" fill="#846c63"/><circle cx="676" cy="137" r="62" fill="#a68b75"/><path fill="#c3c1af" d="M103 91h2v2h-2zm60 48h3v3h-3zm170-54h3v3h-3zm115 61h3v3h-3zm70-65h2v2h-2zm232 10h3v3h-3zm48 64h2v2h-2z"/><path fill="#425552" d="M245 57h12v140h-12zm206 0h12v140h-12zm195 0h12v140h-12z"/><path fill="#59605a" d="M30 208h840v9H30zM30 33h840v15H30zM30 37h14v272H30zm826 0h14v272h-14z"/><path fill="#d5af73" d="M96 38h170v5H96zm265 0h170v5H361zm265 0h170v5H626z"/><path fill="#776451" d="M71 228h128v68H71z"/><path fill="#b29a72" d="M65 222h140v10H65z"/><path fill="#283639" d="M83 244h32v39H83zm46 0h54v39h-54z"/><path fill="#c7ba99" d="M91 204h20v18H91zm45 2h18v16h-18z"/><path fill="#516367" d="M697 222h130v75H697z"/><path fill="#1c2933" d="M709 235h44v50h-44zm54 0h50v50h-50z"/><path fill="#8fb8aa" d="M716 243h30v18h-30z"/><path fill="#c6b38b" d="M773 240h29v4h-29zm0 11h21v4h-21zm0 11h27v4h-27z"/><path fill="#263036" d="M300 340h25v71h-25zm247 0h25v71h-25z"/><path fill="#655347" d="M231 276h426v69H231z"/><path fill="#a48863" d="M220 270h448v57H220z"/><path fill="#bd9c70" d="M220 270h448v7H220z"/>${mugs}<path fill="#465858" d="M202 327h49v59h-49zm437 0h49v59h-49zM317 370h51v58h-51zm211 0h51v58h-51z"/><path fill="#826e53" d="M205 327h46v8h-46zm437 0h46v8h-46zm-322 43h48v8h-48zm211 0h48v8h-48z"/><path fill="#54594e" d="M55 332h74v8H55zm0 17h74v8H55zm0 17h74v8H55z"/><path fill="#5b645b" d="M799 319h42v67h-42z"/><path fill="#a89a73" d="M799 319h42v8h-42z"/><path fill="#798a67" d="M801 295h12v25h-12zm15-13h12v38h-12zm14 18h9v20h-9z"/><path stroke="#6c6b5a" stroke-width="2" d="M20 433h860M60 381h780M174 299l-37 171m596-171 36 171M450 345v125"/><path fill="#d2b981" d="M394 228h105v4H394z"/></svg>${people.map((c,i)=>{const [x,y]=spots[i];return `<button class="mess-person" style="left:${x}%;top:${y}%" data-action="talk-crew" data-id="${c.id}" aria-label="Talk to ${escape(c.name)}">${crewSprite(c,true)}<span>${escape(c.name.split(' ')[0])}</span></button>`;}).join('')}<div class="mess-plaque">${escape(s.shipName.toUpperCase())} / COMMON ROOM <span>${escape(stats(s).name.toUpperCase())}</span></div></div>`;
}
